// Server addresses from the environment; they sit in the message because
// the address field of the HTTP node takes them from there.
msg.aasUrl = env.get('SDI_AAS_URL') || 'http://localhost:8081';
msg.olcaUrl = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';

// ═══════════════════════════════════════════════════════════
// Start the calculation in openLCA.
//
// The quantities come from the DataSources submodel and are assembled in
// the node "Read weight and data sources in use".
//
// IMPORTANT: in olca-schema 2.x the field is called "parameters". The
// former "parameterRedefs" is ignored by openLCA without an error.
// ═══════════════════════════════════════════════════════════
const STANDARD_METHODE = env.get('SDI_OPENLCA_DEFAULT_METHOD')
                      || 'b4571628-4b7b-3e4f-81b1-9a8cca6cb3f8';  // EF 3.0 Method (adapted)

// The selection may also come from another tab. Flow context is scoped to
// one tab; a user interface that sits elsewhere cannot set it. The global
// context is therefore consulted first.
let selectedMethodUUIDs = global.get('selectedMethods')
    || flow.get('selectedMethods') || [];
let selectedMethodNames = global.get('selectedMethodNames')
    || flow.get('selectedMethodNames') || [];

// Without a selection in the dashboard the default method is used
if (selectedMethodUUIDs.length === 0) {
    selectedMethodUUIDs = [STANDARD_METHODE];
    selectedMethodNames = [(flow.get('methodNamesById') || {})[STANDARD_METHODE] || 'default method'];
    flow.set('selectedMethods', selectedMethodUUIDs);
    flow.set('selectedMethodNames', selectedMethodNames);
    node.log('No method chosen, using the default method');
}

let currentIndex = flow.get('methodQueueIndex');
if (currentIndex === undefined) {
    currentIndex = 0;
    flow.set('methodQueueIndex', currentIndex);
    flow.set('aggregatedPcfResults', []);
}

// Every method processed -> pass the results on
if (currentIndex >= selectedMethodUUIDs.length) {
    flow.set('methodQueueIndex', undefined);
    msg.payload = flow.get('aggregatedPcfResults');
    msg.usedDataSources = flow.get('usedDataSources');
    msg.usedDataSourceIds = flow.get('usedDataSourceIds');
    flow.set('step', 'done');
    return [null, msg];
}

const parameters = msg.lcaParameters || flow.get('lcaParameters') || [];
if (parameters.length === 0) {
    node.error('No LCA parameters present. Read the DataSources submodel '
             + 'first, so that quantities and process assignment are known.', msg);
    return null;
}

const currentMethodUUID = selectedMethodUUIDs[currentIndex];
const currentMethodName = selectedMethodNames[currentIndex];
flow.set('currentMethodUUID', currentMethodUUID);
flow.set('currentMethodName', currentMethodName);
flow.set('step', 'calculate');

const productSystem = env.get('SDI_OPENLCA_PRODUCT_SYSTEM') || flow.get('productSystemId');
if (!productSystem) {
    node.error('Product system not set (SDI_OPENLCA_PRODUCT_SYSTEM)', msg);
    return null;
}

const setup = {
    '@type': 'CalculationSetup',
    target: { '@type': 'ProductSystem', '@id': productSystem },
    impactMethod: { '@type': 'ImpactMethod', '@id': currentMethodUUID },
    amount: parseFloat(env.get('SDI_LCA_AMOUNT') || '1'),
    parameters: parameters
};

// Pass the normalisation and weighting set along if the method keeps one.
// The weighted single score is formed from it later.
const nwSets = flow.get('nwSetsByMethod') || {};
const nw = nwSets[currentMethodUUID];
if (nw && nw.id) {
    setup.nwSet = { '@type': 'NwSet', '@id': nw.id };
    flow.set('currentNwSet', nw);
} else {
    flow.set('currentNwSet', null);
}

msg.url = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', id: 1, method: 'result/calculate', params: setup };

node.log('Calculating with ' + parameters.length + ' parameters, method ' + currentMethodName);
node.status({ fill: 'blue', shape: 'dot',
              text: 'calculating ' + (currentIndex + 1) + '/' + selectedMethodUUIDs.length });
return [msg, null];

// Server addresses from the environment; they sit in the message because
// the address field of the HTTP node takes them from there.
msg.aasUrl = env.get('SDI_AAS_URL') || 'http://localhost:8081';
msg.olcaUrl = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';

if (msg.payload.error) {
  node.error("Calculate error: " + msg.payload.error.message, msg);
  return null;
}

const resultId = msg.payload.result?.["@id"];
if (!resultId) {
  node.error("No result ID returned: " + JSON.stringify(msg.payload), msg);
  return null;
}

flow.set("resultId", resultId);
flow.set("step", "check-state");

msg.payload = {
  jsonrpc: "2.0",
  id: 2,
  method: "result/state",
  params: { "@type": "Result", "@id": resultId }
};
return msg;

// Server addresses from the environment; they sit in the message because
// the address field of the HTTP node takes them from there.
msg.aasUrl = env.get('SDI_AAS_URL') || 'http://localhost:8081';
msg.olcaUrl = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';

if (msg.payload.error) {
  node.error("State error: " + msg.payload.error.message, msg);
  return null;
}

const state = msg.payload.result;
const resultId = flow.get("resultId");

if (state?.isReady === true) {
  flow.set("step", "get-impacts");
  msg.payload = {
    jsonrpc: "2.0",
    id: 3,
    method: "result/total-impacts",
    params: { "@type": "Result", "@id": resultId }
  };
  return [msg, null];
} else {
  flow.set("step", "check-state");
  msg.payload = {
    jsonrpc: "2.0",
    id: 2,
    method: "result/state",
    params: { "@type": "Result", "@id": resultId }
  };
  return [null, msg];
}

// Evaluate the impacts and form the weighted single score
if (msg.payload && msg.payload.error) {
    node.error('Error in the impacts: ' + JSON.stringify(msg.payload.error), msg);
    return null;
}

let impacts = [];
if (msg.payload) {
    if (Array.isArray(msg.payload.result)) { impacts = msg.payload.result; }
    else if (Array.isArray(msg.payload)) { impacts = msg.payload; }
}

const parsedImpacts = impacts.map(r => ({
    categoryId: (r.impactCategory || {})['@id'],
    category: (r.impactCategory || {}).name,
    value: r.amount,
    unit: (r.impactCategory || {}).refUnit
}));

// Single score following the EF method: normalise, then weight, then sum.
// The factors come from the normalisation and weighting set of the method,
// not from a separate table.
let singleScore = null;
const nw = flow.get('currentNwSet');
if (nw && nw.factors) {
    let summe = 0;
    let gezaehlt = 0;
    parsedImpacts.forEach(i => {
        const f = nw.factors[i.categoryId];
        if (!f || !f.normalisation || !f.weighting) { return; }
        summe += (i.value / f.normalisation) * f.weighting;
        gezaehlt += 1;
    });
    if (gezaehlt > 0) { singleScore = summe; }
}

const activeMethodUUID = flow.get('currentMethodUUID') || 'unknown';
const activeMethodName = flow.get('currentMethodName') || 'unknown';

const singleResult = {
    processName: env.get('SDI_LCA_PROCESS_NAME') || 'LCA process',
    impactMethod: activeMethodUUID,
    impactMethodName: activeMethodName,
    targetOutput: (function () {
        const n = env.get('SDI_LCA_AMOUNT') || '1';
        return n + (String(n) === '1' ? ' piece' : ' pieces');
    })(),
    allImpacts: parsedImpacts,
    singleScore: singleScore,
    singleScoreUnit: singleScore === null ? '' : 'Pt',
    calculatedAt: new Date().toISOString()
};

const aggregated = flow.get('aggregatedPcfResults') || [];
aggregated.push(singleResult);
flow.set('aggregatedPcfResults', aggregated);
flow.set('methodQueueIndex', (flow.get('methodQueueIndex') || 0) + 1);

node.log(activeMethodName + ': ' + parsedImpacts.length + ' categories'
       + (singleScore !== null ? ', single score ' + singleScore.toExponential(4) + ' Pt' : ''));

// Release the result in openLCA
flow.set('step', 'dispose');
msg.payload = { jsonrpc: '2.0', id: 4, method: 'result/dispose',
                params: { '@type': 'Result', '@id': flow.get('resultId') } };
return msg;

const results = msg.payload;
msg.results = results;

if (!Array.isArray(results) || results.length === 0) {
    msg.payload = "<div style='color: var(--md-sys-color-error, #ff0000); font-weight: bold;'>⚠ Keine LCA-Ergebnisse zur Anzeige vorhanden.</div>";
    return msg;
}

// CSS-Styles für eine saubere Dashboard-Tabelle definieren
let html = `
<style>
    .lca-container { font-family: sans-serif; padding: 8px; }
    .lca-title { margin-bottom: 4px; font-size: 1.4rem; font-weight: bold; }
    .lca-meta { font-size: 0.9rem; color: #777; margin-bottom: 16px; }
    .lca-method-section { margin-top: 24px; }
    .lca-method-title { font-size: 1.15rem; font-weight: bold; margin-bottom: 8px; display: flex; align-items: center; gap: 8px; }
    .lca-table { width: 100%; border-collapse: collapse; margin-bottom: 8px; background: transparent; }
    .lca-table th { text-align: left; padding: 10px; font-weight: bold; border-bottom: 2px solid var(--v-border-color, #ccc); }
    .lca-table td { padding: 8px 10px; border-bottom: 1px solid var(--v-border-color, #eee); }
    .lca-table tr:hover { background-color: rgba(0,0,0,0.03); }
    .text-right { text-align: right; }
    .text-center { text-align: center; }
</style>
<div class="lca-container">
    <div class="lca-title">📊 Ökobilanz-Auswertung (LCA Results)</div>
    <div class="lca-meta">
        <strong>System:</strong> ${results[0].processName}<br>
        <strong>Menge:</strong> ${results[0].targetOutput}<br>
        <em>Berechnet am: ${new Date(results[0].calculatedAt).toLocaleString("de-DE")}</em>
    </div>
`;

// Schleife generiert NUR Tabellen für Methoden, die tatsächlich im Array stecken
results.forEach((res, index) => {
    const methodName = res.impactMethodName || `Methode (${res.impactMethod.substring(0,8)}...)`;

    html += `
    <div class="lca-method-section">
        <div class="lca-method-title">🌍 ${index + 1}. ${methodName}</div>
    `;

    if (!res.allImpacts || res.allImpacts.length === 0) {
        html += `<p style="font-style: italic; color: #888;">Keine Indikatoren für diese Methode vorhanden.</p></div>`;
        return;
    }

    html += `
        <table class="lca-table">
            <thead>
                <tr>
                    <th>Wirkungskategorie</th>
                    <th class="text-right">Wert</th>
                    <th class="text-center">Einheit</th>
                </tr>
            </thead>
            <tbody>
    `;

    res.allImpacts.forEach(imp => {
        let formattedValue = imp.value;
        if (typeof imp.value === 'number') {
            if (imp.value === 0) {
                formattedValue = "0";
            } else if (imp.value < 0.001 && imp.value > 0) {
                formattedValue = imp.value.toExponential(4);
            } else {
                formattedValue = imp.value.toLocaleString("de-DE", { minimumFractionDigits: 2, maximumFractionDigits: 4 });
            }
        }

        html += `
            <tr>
                <td><strong>${imp.category}</strong></td>
                <td class="text-right">${formattedValue}</td>
                <td class="text-center" style="color: #666;">${imp.unit}</td>
            </tr>
        `;
    });

    html += `
            </tbody>
        </table>
    </div>
    `;
});

html += `</div>`;

msg.payload = html;
return msg;

// Server addresses from the environment; they sit in the message because
// the address field of the HTTP node takes them from there.
msg.aasUrl = env.get('SDI_AAS_URL') || 'http://localhost:8081';
msg.olcaUrl = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';

// ═══════════════════════════════════════════════════════════
// Write the LCA results into the ILCD submodel.
// The iteration is named after the data sources actually used, so that
// results of differing data quality can sit side by side.
// ═══════════════════════════════════════════════════════════
const results = msg.results || flow.get('aggregatedPcfResults') || [];

// Without results nothing is written. An empty iteration in the AAS would
// be hard to tell apart from a real result.
if (!results.length || !results.some(r => (r.allImpacts || []).length)) {
    node.error('No calculation results present - no iteration is written. The '
        + 'most common cause is that the IPC server in openLCA is not running '
        + '(Tools -> Developer tools -> IPC Server).', msg);
    node.status({ fill: 'red', shape: 'ring', text: 'no results' });
    return null;
}
msg.ilcdSubmodel = flow.get('ilcdSubmodel') || msg.ilcdSubmodel;

// Flow context holds the latest state: the machine data is only added when
// the parts are read, that is after this message was assembled.
const sourcesLabel = flow.get('usedDataSources') || msg.usedDataSources || 'PLM';
const sourcesIds = flow.get('usedDataSourceIds') || msg.usedDataSourceIds || ['PLM'];

function sanitizeIdShort(str) {
    if (!str) { return 'Unknown'; }
    return str.toString().trim()
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue')
        .replace(/Ä/g, 'Ae').replace(/Ö/g, 'Oe').replace(/Ü/g, 'Ue')
        .replace(/ß/g, 'ss')
        .replace(/[^A-Za-z0-9_]/g, '_')
        .replace(/__+/g, '_').replace(/_+$/, '')
        .replace(/^([0-9])/, '_$1');
}
function byIdShort(arr, id) {
    return (arr || []).find(e => e && e.idShort === id);
}
function setProp(coll, id, value) {
    const p = byIdShort(coll, id);
    if (p) {
        p.value = value === null || value === undefined ? '' : String(value);
    } else {
        node.warn('Property "' + id + '" not found in the ILCD template');
    }
}

if (!msg.payload || !msg.payload.submodelElements || !msg.payload.submodelElements[0]) {
    node.error('The ILCD submodel could not be read', msg);
    return null;
}

const iterationList = msg.payload.submodelElements[0];
if (!Array.isArray(iterationList.value) || iterationList.value.length === 0) {
    node.error('SubmodelElementList "LCAIteration" is empty', msg);
    return null;
}

// Clone the iteration template so that existing iterations are kept
const template = iterationList.value[0];
const iteration = JSON.parse(JSON.stringify(template));

// Form the iteration idShort from the sources used, e.g. "Simulation_PLM_ERP"
iteration.idShort = sourcesIds.map(sanitizeIdShort).join('_').substring(0, 128);

setProp(iteration.value, 'DataSource', sourcesLabel);
setProp(iteration.value, 'TimeOfLCA', results[0] ? results[0].calculatedAt : new Date().toISOString());
const gewicht = msg.partWeight !== null && msg.partWeight !== undefined
    ? msg.partWeight : flow.get('partWeight');
setProp(iteration.value, 'WeightOfPart', gewicht);
setProp(iteration.value, 'TargetOutput', results[0] ? results[0].targetOutput : '');

const lciaMethods = byIdShort(iteration.value, 'LCIAMethods');
if (lciaMethods) {
    lciaMethods.value = results.map(result => ({
        modelType: 'SubmodelElementCollection',
        idShort: sanitizeIdShort(result.impactMethodName || result.impactMethod),
        value: (result.allImpacts || []).map(impact => ({
            modelType: 'SubmodelElementCollection',
            idShort: sanitizeIdShort(impact.category),
            value: [
                { modelType: 'Property', valueType: 'xs:double', idShort: 'Value',
                  value: impact.value !== null && impact.value !== undefined ? String(impact.value) : '' },
                { modelType: 'Property', valueType: 'xs:string', idShort: 'Unit',
                  value: impact.unit || '' }
            ]
        }))
    }));
} else {
    node.warn('SML "LCIAMethods" not found in the submodel');
}

// Replace an existing iteration of the same name, otherwise append it.
// The unfilled placeholder of the template is removed in the process. It
// used to be called "<DataSource>"; angle brackets are not permitted in an
// idShort, so it is now called DataSourceTemplate.
const VORLAGEN = ['DataSourceTemplate', 'LCIAMethodTemplate'];
const cleaned = iterationList.value.filter(it =>
    it.idShort && it.idShort.indexOf('<') !== 0
    && VORLAGEN.indexOf(it.idShort) < 0
    && it.idShort !== iteration.idShort);
cleaned.push(iteration);
iterationList.value = cleaned;

node.log('LCA iteration "' + iteration.idShort + '" written (sources: ' + sourcesLabel + ')');
node.status({ fill: 'green', shape: 'dot', text: sourcesLabel });
return msg;

// Server addresses from the environment; they sit in the message because
// the address field of the HTTP node takes them from there.
msg.aasUrl = env.get('SDI_AAS_URL') || 'http://localhost:8081';
msg.olcaUrl = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';

// ═══════════════════════════════════════════════════════════
// Read the weight, determine the data sources and assemble the LCA
// parameters.
//
// Quantities come from the product shell, the manufacturing energy per part
// from the shell of that part. The part shell is derived from the part
// name, following the same naming rule as the idShorts.
//
// In:  msg.payload = DataSources submodel of the product shell
// Out: msg.partSubmodels = part submodels still to be fetched
// ═══════════════════════════════════════════════════════════
const sm = msg.payload;
const byIdShort = (arr, id) => (arr || []).find(e => e && e.idShort === id);
const propValue = (coll, id) => { const p = byIdShort(coll.value, id); return p ? p.value : null; };

const list = byIdShort(sm.submodelElements, 'DataSources')
          || byIdShort(sm.submodelElements, 'Data Sources')
          || (sm.submodelElements || []).find(e => e.modelType === 'SubmodelElementList');
if (!list || !Array.isArray(list.value)) {
    node.error('SubmodelElementList "DataSources" not found', msg);
    return null;
}

// --- Weight -----------------------------------------------------------------
// Same order of preference as for the quantities: PLM, else ERP, else the
// sum of the bill of material. The sum is added further below, once the
// bill of material is known.
const plm = byIdShort(list.value, 'PLM')
         || byIdShort(list.value, 'EngineeringData_PLM') || byIdShort(list.value, 'Engineering Data / PLM');
const gewicht = plm ? byIdShort(plm.value, 'Weight') : null;
msg.partWeight = gewicht && String(gewicht.value).trim() !== '' ? gewicht.value : null;

if (msg.partWeight === null) {
    const erp = (byIdShort(list.value, 'ERP') || byIdShort(list.value, 'ERPData'));
    const erpGewicht = erp ? byIdShort(erp.value, 'ProductWeight') : null;
    if (erpGewicht && String(erpGewicht.value).trim() !== '') {
        msg.partWeight = erpGewicht.value;
    }
}

// --- Data sources that carry values ------------------------------------------
const META = ['DataSource', 'SourceSystem', 'WeightUnit', 'TotalMassUnit',
              'ProductWeightUnit', 'QuantityUnit', 'OrderUnit', 'CycleTimeUnit',
              'ProcessDurationUnit', 'EnergyPerUnitUnit', 'TotalEnergyPerUnitUnit',
              'AveragePowerUnit', 'ServerIP', 'MachineName',
              'LCAProcessId', 'LCAParameterName', 'LCAZeroParameters', 'LCAFlowId'];
function belegt(el) {
    if (!el) { return false; }
    if (el.modelType === 'Property') {
        if (META.indexOf(el.idShort) >= 0) { return false; }
        return el.value !== null && el.value !== undefined && String(el.value).trim() !== '';
    }
    if (Array.isArray(el.value)) { return el.value.some(belegt); }
    return false;
}

// One designation per data source. Depending on where they came from, the
// shells spell the same source differently - "Engineering Data / PLM" from
// the PLM, "ERP-Data" from the ERP. For the identifier of the result only
// which system delivered the data counts. The idShort decides, not the
// label: it is the stable one.
const BEZEICHNUNG = {
    'EngineeringData_PLM': 'PLM',
    'Engineering Data / PLM': 'PLM',
    'ERPData': 'ERP',
    'ERP-Data': 'ERP',
    'Simulation': 'Simulation',
    'Manufacturing': 'MachineData',
    'MachineData': 'MachineData',
    'PLM': 'PLM',
    'ERP': 'ERP'
};
function bezeichne(q) {
    if (BEZEICHNUNG[q.idShort]) { return BEZEICHNUNG[q.idShort]; }
    const label = byIdShort(q.value, 'DataSource');
    const wert = label && label.value ? String(label.value) : q.idShort;
    return BEZEICHNUNG[wert] || wert;
}

const quellenNamen = [];
const quellenIds = [];
list.value.forEach(q => {
    if (!q || !belegt(q)) { return; }
    quellenNamen.push(bezeichne(q));
    quellenIds.push(q.idShort);
});

// --- Quantities from the best available source -------------------------------
const MENGEN_QUELLEN = ['MachineData', 'Manufacturing', 'ERP', 'ERPData', 'PLM', 'EngineeringData_PLM', 'Engineering Data / PLM'];
const parameters = [];
const uebersprungen = [];
const herkunft = [];
let stueckliste = null;
let mengenQuelle = null;

for (const name of MENGEN_QUELLEN) {
    const q = byIdShort(list.value, name);
    const b = q ? byIdShort(q.value, 'BillOfMaterial') : null;
    if (b && Array.isArray(b.value) && b.value.length > 0) {
        stueckliste = b; mengenQuelle = q; break;
    }
}
if (stueckliste) {
    stueckliste.value.forEach(k => {
        const name = propValue(k, 'ComponentName') || k.idShort;
        const masse = parseFloat(propValue(k, 'TotalMass'));
        const prozess = propValue(k, 'LCAProcessId');
        const parameter = propValue(k, 'LCAParameterName');
        const nullen = (propValue(k, 'LCAZeroParameters') || '')
            .split(',').map(s => s.trim()).filter(Boolean);
        if (!prozess || !parameter || isNaN(masse)) { uebersprungen.push('quantity: ' + name); return; }
        const kontext = { '@type': 'Process', '@id': prozess };
        parameters.push({ '@type': 'ParameterRedef', name: parameter, value: masse, context: kontext });
        nullen.forEach(n => parameters.push(
            { '@type': 'ParameterRedef', name: n, value: 0, context: kontext }));
    });
    herkunft.push('quantities from ' + (propValue(mengenQuelle, 'DataSource') || mengenQuelle.idShort));
}

// --- Assembly energy from the product shell ----------------------------------
function energieAus(quelle, behaelterNamen) {
    const q = byIdShort(list.value, quelle);
    if (!q) { return 0; }
    let b = null;
    for (const bn of [].concat(behaelterNamen)) {
        const k = byIdShort(q.value, bn);
        if (k && Array.isArray(k.value) && k.value.length > 0) { b = k; break; }
    }
    if (!b) { return 0; }
    let gezaehlt = 0;
    b.value.forEach(e => {
        const wert = parseFloat(propValue(e, 'EnergyPerUnit'));
        const prozess = propValue(e, 'LCAProcessId');
        const parameter = propValue(e, 'LCAParameterName');
        if (!prozess || !parameter || isNaN(wert)) { return; }
        const vorhanden = parameters.find(p => p.name === parameter && p.context['@id'] === prozess);
        if (vorhanden) { vorhanden.value += wert; }
        else { parameters.push({ '@type': 'ParameterRedef', name: parameter, value: wert,
                                 context: { '@type': 'Process', '@id': prozess } }); }
        gezaehlt += 1;
    });
    return gezaehlt;
}
if ((energieAus('MachineData', 'ManufacturingProcesses')
     || energieAus('Manufacturing', 'ManufacturingProcesses')) > 0) {
    herkunft.push('assembly energy from MachineData');
} else if (energieAus('Simulation', 'SimulationProcesses') > 0) {
    herkunft.push('assembly energy from Simulation');
}

// --- Part shells whose manufacturing energy still has to be fetched ----------
function aasName(str) {
    let s = String(str || '')
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue')
        .replace(/Ä/g, 'Ae').replace(/Ö/g, 'Oe').replace(/Ü/g, 'Ue').replace(/ß/g, 'ss')
        .replace(/[^A-Za-z0-9_]/g, '_').replace(/__+/g, '_').replace(/_+$/, '');
    return s;
}
const basis = env.get('SDI_AAS_BASE') || 'localhost/demo/aas';
const bauteile = [];
if (stueckliste) {
    stueckliste.value.forEach(k => {
        const name = propValue(k, 'ComponentName');
        if (!name) { return; }
        bauteile.push({ name: name,
                        submodelId: basis + '/' + aasName(name) + '/DataSources' });
    });
}

// If the weight is still open, it is summed from the bill of material.
if (msg.partWeight === null && stueckliste) {
    const summe = stueckliste.value.reduce((s, k) => {
        const m = parseFloat(propValue(k, 'TotalMass'));
        return isNaN(m) ? s : s + m;
    }, 0);
    if (summe > 0) { msg.partWeight = summe; }
}

msg.usedDataSources = quellenNamen.join(', ');
msg.usedDataSourceIds = quellenIds;
msg.lcaParameters = parameters;
msg.partSubmodels = bauteile;

flow.set('partWeight', msg.partWeight);
flow.set('lcaParameters', parameters);
flow.set('usedDataSources', msg.usedDataSources);
flow.set('usedDataSourceIds', quellenIds);
flow.set('partSubmodels', bauteile);
flow.set('partIndex', 0);
flow.set('herkunft', herkunft);

if (uebersprungen.length > 0) { node.warn('Without an assignment: ' + uebersprungen.join(', ')); }
node.log('Product shell: ' + herkunft.join(', ') + ' | ' + parameters.length
       + ' parameters | ' + bauteile.length + ' part shells to fetch');
msg.payload = '';
return msg;

// Server addresses from the environment; they sit in the message because
// the address field of the HTTP node takes them from there.
msg.aasUrl = env.get('SDI_AAS_URL') || 'http://localhost:8081';
msg.olcaUrl = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';

msg.url = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', id: 1, method: 'data/get/descriptors',
                params: { '@type': 'ImpactMethod' } };
return msg;

// ═══════════════════════════════════════════════════════════
// Load the impact methods from openLCA.
// Fills the dashboard dropdown with the methods actually present and keeps
// the normalisation and weighting set of each one.
// ═══════════════════════════════════════════════════════════
if (!msg.payload || !Array.isArray(msg.payload.result)) {
    node.error('The method list could not be read', msg);
    return null;
}

const methoden = msg.payload.result
    .map(m => ({ id: m['@id'], name: m.name }))
    .sort((a, b) => a.name.localeCompare(b.name));

const namenById = {};
methoden.forEach(m => { namenById[m.id] = m.name; });
flow.set('methodNamesById', namenById);
flow.set('methodList', methoden);

msg.ui_update = {
    options: methoden.map(m => ({ label: m.name, value: m.id + ' | ' + m.name }))
};

const standard = env.get('SDI_OPENLCA_DEFAULT_METHOD')
              || 'b4571628-4b7b-3e4f-81b1-9a8cca6cb3f8';
if (namenById[standard]) {
    msg.payload = standard + ' | ' + namenById[standard];
    node.log(methoden.length + ' methods loaded, default: ' + namenById[standard]);
} else {
    msg.payload = '';
    node.warn(methoden.length + ' methods loaded, default method not found');
}
node.status({ fill: 'green', shape: 'dot', text: methoden.length + ' methods' });
return msg;

// Server addresses from the environment; they sit in the message because
// the address field of the HTTP node takes them from there.
msg.aasUrl = env.get('SDI_AAS_URL') || 'http://localhost:8081';
msg.olcaUrl = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';

const id = env.get('SDI_OPENLCA_DEFAULT_METHOD')
       || 'b4571628-4b7b-3e4f-81b1-9a8cca6cb3f8';
msg.url = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';
msg.headers = { 'Content-Type': 'application/json' };
msg.payload = { jsonrpc: '2.0', id: 2, method: 'data/get',
                params: { '@type': 'ImpactMethod', '@id': id } };
return msg;

// Keep the normalisation and weighting sets of the methods.
// In: msg.payload = the complete ImpactMethod from openLCA
const m = msg.payload ? msg.payload.result : null;
if (!m) { return null; }

const saetze = flow.get('nwSetsByMethod') || {};
const nwSet = (m.nwSets || [])[0];
if (nwSet) {
    const factors = {};
    (nwSet.factors || []).forEach(f => {
        const id = (f.impactCategory || {})['@id'];
        if (!id) { return; }
        factors[id] = { normalisation: f.normalisationFactor, weighting: f.weightingFactor };
    });
    saetze[m['@id']] = { id: nwSet['@id'], name: nwSet.name, factors: factors };
    node.log('NW set "' + nwSet.name + '" loaded with ' + Object.keys(factors).length + ' factors');
} else {
    saetze[m['@id']] = null;
    node.log('Method "' + m.name + '" keeps no NW set - no single score possible');
}
flow.set('nwSetsByMethod', saetze);
return msg;

// Fetch the manufacturing energy from the next part shell.
// Output 1: request another part shell, output 2: done
const cfg = { aasUrl: env.get('SDI_AAS_URL') || 'http://localhost:8081' };
const liste = flow.get('partSubmodels') || [];
let i = flow.get('partIndex') || 0;

// Evaluate the answer to the previous request
if (msg.payload && msg.payload.submodelElements) {
    const byIdShort = (arr, id) => (arr || []).find(e => e && e.idShort === id);
    const propValue = (c, id) => { const p = byIdShort(c.value, id); return p ? p.value : null; };
    const sml = byIdShort(msg.payload.submodelElements, 'DataSources')
             || msg.payload.submodelElements.find(e => e.modelType === 'SubmodelElementList');
    const mfg = sml ? (byIdShort(sml.value, 'MachineData') || byIdShort(sml.value, 'Manufacturing')) : null;
    const proc = mfg ? byIdShort(mfg.value, 'ManufacturingProcesses') : null;
    const parameters = flow.get('lcaParameters') || [];
    const herkunft = flow.get('herkunft') || [];
    let gezaehlt = 0;
    if (proc && Array.isArray(proc.value)) {
        proc.value.forEach(e => {
            const wert = parseFloat(propValue(e, 'EnergyPerUnit'));
            const prozess = propValue(e, 'LCAProcessId');
            const parameter = propValue(e, 'LCAParameterName');
            if (!prozess || !parameter || isNaN(wert)) { return; }
            const vorhanden = parameters.find(p => p.name === parameter
                                                && p.context['@id'] === prozess);
            if (vorhanden) { vorhanden.value += wert; }
            else { parameters.push({ '@type': 'ParameterRedef', name: parameter, value: wert,
                                     context: { '@type': 'Process', '@id': prozess } }); }
            gezaehlt += 1;
        });
    }
    if (gezaehlt > 0) {
        const bauteil = (liste[i - 1] || {}).name || 'part';
        herkunft.push('manufacturing energy ' + bauteil);
        flow.set('herkunft', herkunft);

        // Note the machine data as a source of its own. It lives in the part
        // shells rather than in the product shell, and was therefore missing
        // from the identifier of the result - although its values do go in.
        // The designation is the same one the reading node uses, so that the
        // identifiers of product and part agree.
        const bezeichnung = 'MachineData';
        const namen = String(flow.get('usedDataSources') || '')
            .split(',').map(s => s.trim()).filter(Boolean);
        if (namen.indexOf(bezeichnung) < 0) {
            namen.push(bezeichnung);
            flow.set('usedDataSources', namen.join(', '));
        }
        // Record which part delivered the machine data. Only its result may
        // name the machines as a source later on - for the other parts the
        // statement would simply be untrue.
        const gemessen = flow.get('maschinenBauteile') || [];
        if (gemessen.indexOf(bauteil) < 0) {
            gemessen.push(bauteil);
            flow.set('maschinenBauteile', gemessen);
        }
        flow.set('maschinenQuelle', bezeichnung);

        const kennungen = flow.get('usedDataSourceIds') || [];
        if (kennungen.indexOf('MachineData') < 0) {
            kennungen.push('MachineData');
            flow.set('usedDataSourceIds', kennungen);
        }
        node.log('Manufacturing energy from ' + bauteil + ': ' + gezaehlt + ' values');
    }
flow.set('lcaParameters', parameters);
}

// Request the next part shell
while (i < liste.length) {
    const eintrag = liste[i];
    i += 1;
    flow.set('partIndex', i);
    const b64 = Buffer.from(eintrag.submodelId, 'utf8').toString('base64')
        .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
    msg.method = 'GET';
    msg.url = cfg.aasUrl + '/submodels/' + b64;
    msg.headers = { 'Accept': 'application/json' };
    msg.payload = '';
    node.status({ fill: 'blue', shape: 'dot', text: 'part ' + i + '/' + liste.length });
    return [msg, null];
}

// Done
msg.lcaParameters = flow.get('lcaParameters');
msg.usedDataSources = flow.get('usedDataSources');
msg.usedDataSourceIds = flow.get('usedDataSourceIds');
node.log('Parameters complete: ' + msg.lcaParameters.length
       + ' | ' + (flow.get('herkunft') || []).join(', '));
node.status({ fill: 'green', shape: 'dot', text: msg.lcaParameters.length + ' parameters' });
return [null, msg];

// Server addresses from the environment; they sit in the message because
// the address field of the HTTP node takes them from there.
msg.aasUrl = env.get('SDI_AAS_URL') || 'http://localhost:8081';
msg.olcaUrl = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';

// ═══════════════════════════════════════════════════════════
// Write the partial result of each part into that part's ILCD.
//
// The sequence, one request per pass:
//   1. fetch the process list of the calculation (tech-flows)
//   2. ask for the share of each part (total-impacts-of)
//   3. read the ILCD of the part
//   4. write the iteration into it
// The result is released in openLCA afterwards.
// ═══════════════════════════════════════════════════════════
const OLCA = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';
const AAS = env.get('SDI_AAS_URL') || 'http://localhost:8081';

function b64(text) {
    return Buffer.from(text, 'utf8').toString('base64')
        .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function aasName(s) {
    return String(s || '')
        .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue')
        .replace(/Ä/g, 'Ae').replace(/Ö/g, 'Oe').replace(/Ü/g, 'Ue').replace(/ß/g, 'ss')
        .replace(/[^A-Za-z0-9_]/g, '_').replace(/__+/g, '_').replace(/_+$/, '');
}
function prop(id, wert, typ) {
    return { modelType: 'Property', idShort: id, valueType: typ || 'xs:string',
             value: wert === null || wert === undefined ? '' : String(wert) };
}
function rpc(methode, parameter) {
    return { url: OLCA, method: 'POST', headers: { 'Content-Type': 'application/json' },
             payload: { jsonrpc: '2.0', id: 7, method: methode, params: parameter } };
}
function ergebnis(payload) {
    if (!payload) { return null; }
    return payload.result !== undefined ? payload.result : payload;
}

const phase = flow.get('tePhase') || 'start';
const bauteile = flow.get('partSubmodels') || [];
const resultId = flow.get('resultId');

// Without a calculation result or without parts there is nothing to do
if (phase === 'start' && (!resultId || bauteile.length === 0)) {
    flow.set('tePhase', null);
    node.log('No partial results: ' + (!resultId ? 'no calculation' : 'no parts'));
    return [null, msg];
}

// ---------------------------------------------------------------- 1. processes
if (phase === 'start') {
    flow.set('tePhase', 'prozesse');
    flow.set('teIndex', 0);
    flow.set('teGeschrieben', 0);
    return [Object.assign({}, msg, rpc('result/tech-flows', { '@id': resultId })), null];
}

if (phase === 'prozesse') {
    const tf = ergebnis(msg.payload) || [];
    flow.set('teTechFlows', tf);
    node.log('Partial results: ' + tf.length + ' processes in the calculation, '
           + bauteile.length + ' parts');
    flow.set('tePhase', 'anteil');
    // falls through to the next request
}

// -------------------------------------------------- 2. share of one part
if (flow.get('tePhase') === 'anteil') {
    const i = flow.get('teIndex') || 0;
    if (i >= bauteile.length) {
        node.log('Partial results written: ' + (flow.get('teGeschrieben') || 0)
               + ' of ' + bauteile.length);
        flow.set('tePhase', null);
        return [null, msg];
    }
    const bauteil = bauteile[i];
    const kurz = aasName(bauteil.name);
    const tfs = flow.get('teTechFlows') || [];
    // The process is found by name - the same rule as for the shells. The
    // first part of the name is enough, because in the model the processes
    // are called "LCA Prozess: Huelse" and the shell "Huelse_Aluminium".
    const stamm = kurz.split('_')[0];
    const treffer = tfs.find(t => aasName((t.provider || {}).name || '').indexOf(stamm) >= 0);
    if (!treffer) {
        node.warn('No process in the product system for ' + bauteil.name);
        flow.set('teIndex', i + 1);
        return [Object.assign({}, msg, rpc('result/tech-flows', { '@id': resultId })), null];
    }
    flow.set('teBauteil', { name: bauteil.name, kurz: kurz });
    flow.set('tePhase', 'lesen');
    return [Object.assign({}, msg,
        rpc('result/total-impacts-of', { '@id': resultId, techFlow: treffer })), null];
}

// ------------------------------------------------------- 3. ILCD of the part
if (flow.get('tePhase') === 'lesen') {
    flow.set('teAnteil', ergebnis(msg.payload) || []);
    const b = flow.get('teBauteil');
    flow.set('tePhase', 'schreiben');
    const basis = env.get('SDI_AAS_BASE') || 'localhost/demo/aas';
    return [Object.assign({}, msg, {
        url: AAS + '/submodels/' + b64(basis + '/' + b.kurz + '/ILCD'),
        method: 'GET', headers: {}, payload: '' }), null];
}

// ------------------------------------------------------------- 4. writing
if (flow.get('tePhase') === 'schreiben') {
    const b = flow.get('teBauteil');
    const anteil = flow.get('teAnteil') || [];
    const sm = msg.payload;
    const i = flow.get('teIndex') || 0;

    if (!sm || !sm.submodelElements) {
        node.warn('No ILCD submodel for ' + b.name);
        flow.set('teIndex', i + 1);
        flow.set('tePhase', 'anteil');
        return [Object.assign({}, msg, rpc('result/tech-flows', { '@id': resultId })), null];
    }

    const methode = flow.get('currentMethodName') || 'method';
    // The identifier of the data sources is the same as in the product, so
    // that the partial and the total result of one run can be matched.
    //
    // The source list of the product only holds for a part in part: machine
    // data always concerns one particular part. If none was measured for
    // this one, the machine is not named here, even though it did go into
    // the total.
    const maschinenQuelle = flow.get('maschinenQuelle') || 'MachineData';
    const gemessene = flow.get('maschinenBauteile') || [];
    let quellen = flow.get('usedDataSources')
        || (flow.get('herkunft') || []).join(', ') || 'unknown';
    if (gemessene.indexOf(b.name) < 0) {
        quellen = quellen.split(',').map(s => s.trim())
            .filter(s => s && s !== maschinenQuelle).join(', ');
    }
    // Where the individual quantities came from stands beside them.
    const herkunft = (flow.get('herkunft') || []).join(', ');
    const nw = flow.get('currentNwSet');
    let einzelwert = null;
    if (nw && nw.factors) {
        let summe = 0, gezaehlt = 0;
        anteil.forEach(a => {
            const f = nw.factors[(a.impactCategory || {})['@id']];
            if (!f || !f.normalisation || !f.weighting) { return; }
            summe += (a.amount / f.normalisation) * f.weighting;
            gezaehlt += 1;
        });
        if (gezaehlt > 0) { einzelwert = summe; }
    }

    const kategorien = anteil.map(a => ({
        modelType: 'SubmodelElementCollection',
        idShort: aasName((a.impactCategory || {}).name),
        value: [prop('Value', a.amount, 'xs:double'),
                prop('Unit', (a.impactCategory || {}).refUnit || '')]
    }));

    let liste = sm.submodelElements[0];
    if (!liste || !Array.isArray(liste.value)) {
        liste = { modelType: 'SubmodelElementCollection', idShort: 'LCAIteration', value: [] };
        sm.submodelElements = [liste];
    }

    // The iteration carries the same name as the one on the product, so that
    // the partial and the total result of a run can be matched.
    const name = aasName(quellen).substring(0, 100) || 'PartialResult';
    let iteration = liste.value.find(x => x && x.idShort === name);
    if (!iteration) {
        iteration = { modelType: 'SubmodelElementCollection', idShort: name, value: [] };
        liste.value = liste.value.filter(x => x && x.idShort
            && x.idShort.indexOf('<') !== 0
            && ['DataSourceTemplate', 'LCIAMethodTemplate'].indexOf(x.idShort) < 0);
        liste.value.push(iteration);
    }

    const feste = [
        prop('DataSource', quellen),
        prop('TimeOfLCA', new Date().toISOString(), 'xs:dateTime'),
        prop('DataOrigin', herkunft),
        prop('PartOfProduct', flow.get('produktName') || 'Kugelschreiber_TracePEN'),
        // Only create the single score when the method knows one. An empty
        // number typed xs:double is invalid under the specification and is
        // reported when the package is checked: EN 15804 keeps no single
        // score, EF 3.0 does.
        ...(einzelwert === null ? [] : [
            prop('SingleScore', einzelwert, 'xs:double'),
            prop('SingleScoreUnit', 'Pt')
        ])
    ];
    // Remove what is not written this time round as well.
    //
    // Leaving a field out is not enough: the old entry then stays in the
    // shell. That is exactly how an empty single score survived from the
    // previous run and was reported when the package was checked, although
    // the fault had seemed fixed long before.
    const AUFRAEUMEN = ['SingleScore', 'SingleScoreUnit'];
    iteration.value = iteration.value.filter(x =>
        x && feste.every(f => f.idShort !== x.idShort)
          && !(AUFRAEUMEN.indexOf(x.idShort) >= 0
               && !feste.some(f => f.idShort === x.idShort)));
    feste.forEach(f => iteration.value.push(f));

    let methoden = iteration.value.find(x => x && x.idShort === 'LCIAMethods');
    if (!methoden) {
        methoden = { modelType: 'SubmodelElementCollection', idShort: 'LCIAMethods', value: [] };
        iteration.value.push(methoden);
    }
    methoden.value = (methoden.value || []).filter(x => x && x.idShort !== aasName(methode));
    methoden.value.push({ modelType: 'SubmodelElementCollection',
                          idShort: aasName(methode), value: kategorien });

    const klima = anteil.find(a => (a.impactCategory || {}).name === 'Climate change');
    node.log('Partial result ' + b.name + ': ' + kategorien.length + ' categories'
           + (klima ? ', climate change ' + klima.amount.toFixed(6) + ' kg CO2 eq' : ''));

    flow.set('teGeschrieben', (flow.get('teGeschrieben') || 0) + 1);
    flow.set('teIndex', i + 1);
    flow.set('tePhase', 'anteil');
    return [Object.assign({}, msg, {
        url: msg.url, method: 'PUT',
        headers: { 'Content-Type': 'application/json' }, payload: sm }), null];
}

return [null, msg];

// Server addresses from the environment; they sit in the message because
// the address field of the HTTP node takes them from there.
msg.aasUrl = env.get('SDI_AAS_URL') || 'http://localhost:8081';
msg.olcaUrl = env.get('SDI_OPENLCA_URL') || 'http://localhost:8080';

// Set the shell and request its DataSources submodel.
// The same effect as choosing it in the dashboard.
const basis = env.get('SDI_AAS_BASE') || 'localhost/demo/aas';
const aas = env.get('SDI_LCA_SHELL') || (basis + '/Kugelschreiber_TracePEN');
const server = env.get('SDI_AAS_URL') || 'http://localhost:8081';

function b64(text) {
    return Buffer.from(text, 'utf8').toString('base64')
        .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

global.set('dashboardShell', aas);
flow.set('produktName', aas.split('/').pop());

// The HTTP node composes the address from the environment variable and
// this identifier.
msg.dsSubmodel = b64(aas + '/DataSources');
msg.ilcdSubmodel = b64(aas + '/ILCD');
// Put it in flow context as well: the end of the run takes the identifier
// from there, because by then the message has been replaced.
flow.set('ilcdSubmodel', b64(aas + '/ILCD'));
flow.set('dsSubmodel', b64(aas + '/DataSources'));
msg.payload = '';
node.log('Chain started for ' + aas);
return msg;
